                      />

                      <FormField
                        control={form.control}
                        name="topic2"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Topic 2 (Optional)</FormLabel>
                            <FormControl>
                              <Input 
                                placeholder="e.g., Photosynthesis" 
                                {...field}
                                data-testid="input-topic2"
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="topic3"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Topic 3 (Optional)</FormLabel>
                            <FormControl>
                              <Input 
                                placeholder="e.g., French Verbs" 
                                {...field}
                                data-testid="input-topic3"
                              />
                            </FormControl>
                            <FormMessage />
