                      />

                      <FormField
                        control={form.control}
                        name="topic4"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Topic 4 (Optional)</FormLabel>
                            <FormControl>
                              <Input 
                                placeholder="e.g., Cell Structure" 
                                {...field}
